#' Bootstrap EGA
#'
#' Checks whether the dimensions found by Exploratory Graph Analysis replicate 
#' across bootstrap samples, with the distribution of the number of 
#' dimensions, the structural consistency of each dimension and the stability 
#' of each item's membership.
#' 
#' @param data .
#' @param vars .
#' @param reportLang .
#' @param corr .
#' @param naData .
#' @param model .
#' @param algorithm .
#' @param uniMethod .
#' @param runBoot .
#' @param bootType .
#' @param iter .
#' @param seed .
#' @param stabilityCut .
#' @param showChoicesGuide .
#' @param showItemPlot .
#' @param showFrequencyPlot .
#' @param plotPalette .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$intro} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$choicesGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$status} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summaryGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$frequency} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$dimStability} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$itemStability} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$interpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$itemPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$frequencyPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
bootega <- function(
    data,
    vars,
    reportLang = "en",
    corr = "auto",
    naData = "pairwise",
    model = "glasso",
    algorithm = "walktrap",
    uniMethod = "louvain",
    runBoot = FALSE,
    bootType = "parametric",
    iter = 500,
    seed = 2026,
    stabilityCut = 0.7,
    showChoicesGuide = TRUE,
    showItemPlot = TRUE,
    showFrequencyPlot = TRUE,
    plotPalette = "jamovi") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("bootega requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL))


    options <- bootegaOptions$new(
        vars = vars,
        reportLang = reportLang,
        corr = corr,
        naData = naData,
        model = model,
        algorithm = algorithm,
        uniMethod = uniMethod,
        runBoot = runBoot,
        bootType = bootType,
        iter = iter,
        seed = seed,
        stabilityCut = stabilityCut,
        showChoicesGuide = showChoicesGuide,
        showItemPlot = showItemPlot,
        showFrequencyPlot = showFrequencyPlot,
        plotPalette = plotPalette)

    analysis <- bootegaClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

